from decimal import Decimal
from typing import Any


def _line_number(value: Any) -> Decimal:
    if value is None:
        return Decimal(0)
    if isinstance(value, str):
        value = value.strip()
        if value == "":
            return Decimal(0)
    return Decimal(str(value))


def renumber(lines: list[dict]) -> list[dict]:
    grouped: dict[str, list[tuple[Decimal, int, dict]]] = {}

    for position, row in enumerate(lines):
        if row.get("DEL_FLG", "") == "Y":
            continue

        order_id = str(row.get("ORD_ID", ""))
        grouped.setdefault(order_id, []).append(
            (_line_number(row.get("LINE_NO", "")), position, row)
        )

    result: list[dict] = []
    for order_id in sorted(grouped):
        rows = sorted(grouped[order_id], key=lambda item: (item[0], item[1]))
        for new_line_no, (_, _, row) in enumerate(rows, start=1):
            copied = dict(row)
            copied["LINE_NO"] = new_line_no
            result.append(copied)

    return result
